Sort the bookings by start time, then sweep with a min-heap of end times. For each booking, if the earliest end is less than or equal to the new start, reuse that room by popping it; otherwise open a new one. Push the current end, and the heap size at the end is the answer.

```js
function minRooms(bookings) {
  if (bookings.length === 0) return 0;
  const sorted = [...bookings].sort((a, b) => a[0] - b[0]);
  const heap = []; // min-heap of end times

  const push = (x) => {
    heap.push(x);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (heap[p] <= heap[i]) break;
      [heap[p], heap[i]] = [heap[i], heap[p]];
      i = p;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let s = i;
        if (l < heap.length && heap[l] < heap[s]) s = l;
        if (r < heap.length && heap[r] < heap[s]) s = r;
        if (s === i) break;
        [heap[s], heap[i]] = [heap[i], heap[s]];
        i = s;
      }
    }
    return top;
  };

  for (const [start, end] of sorted) {
    if (heap.length && heap[0] <= start) pop();
    push(end);
  }
  return heap.length;
}
```

Time is O(n log n) from the sort and the heap, space O(n) for the heap. The `<=` is what lets a booking starting exactly when another ends share the room.
